const body = $json.body ?? $json;
const spreadsheetId = String(body.spreadsheetId ?? '');
const destinationSheet = String(body.destinationSheet ?? '');
const contacts = Array.isArray(body.contacts) ? body.contacts : [];
if (!/^[a-zA-Z0-9_-]{20,200}$/.test(spreadsheetId)) throw new Error('Invalid spreadsheet ID');
if (destinationSheet !== 'GTM Clean') throw new Error('Destination must be GTM Clean');
if (!contacts.length || contacts.length > 1000) throw new Error('Expected 1-1000 clean contacts');
return [{ json: { spreadsheetId, destinationSheet, contacts } }];

const batch = $('Validate and Shape Clean Rows').first().json;
const blockingFlags = new Set(['invalid_email', 'missing_company', 'missing_owner', 'stage_regression', 'duplicate_identity']);
const safeCell = (value) => { const text = String(value ?? ''); return /^[=+\-@]/.test(text) ? `'${text}` : text; };
return batch.contacts.filter((contact) => contact.recordStatus === 'active' && !(Array.isArray(contact.qualityFlags) ? contact.qualityFlags : []).some((flag) => blockingFlags.has(flag))).map((contact) => ({ json: {
  contact_id: safeCell(contact.contactId), full_name: safeCell(contact.fullName),
  email: safeCell(String(contact.normalizedEmail ?? contact.rawEmail ?? '').toLowerCase()),
  company: safeCell(contact.company), phone: safeCell(contact.phone),
  job_title: safeCell(contact.jobTitle), website: safeCell(contact.website),
  region: safeCell(contact.region), segment: safeCell(contact.segment),
  lifecycle_stage: safeCell(contact.lifecycleStage), owner_id: safeCell(contact.ownerId),
  quality_flags: safeCell(Array.isArray(contact.qualityFlags) ? contact.qualityFlags.join('|') : '')
} }));
